const fresh=()=>({version:1,results:{},bookmarks:[],sessions:[],active:null});
function cleanSession(s){
 if(!s||!Array.isArray(s.ids))return null;
 const ids=[...new Set(s.ids.filter(id=>byId.has(id)))].slice(0,Q.length);if(!ids.length)return null;
 const answers={};for(const id of ids)if([1,2,3,4].includes(s.answers?.[id]))answers[id]=s.answers[id];
 return {id:String(s.id||Date.now()).slice(0,100),title:String(s.title||'나의 학습').slice(0,100),ids,answers,index:(()=>{const at=Number.isInteger(s.index)?s.index:0,next=s.ids.slice(Math.max(0,at)).find(id=>ids.includes(id));return next!==undefined?ids.indexOf(next):Math.max(0,Math.min(ids.length-1,at));})(),startedAt:Number(s.startedAt)||Date.now(),finishedAt:Number(s.finishedAt)||null};
}
function cleanState(raw){
 if(!raw||raw.version!==1||!raw.results||!Array.isArray(raw.bookmarks)||!Array.isArray(raw.sessions))throw Error('format');
 const s=fresh();s.bookmarks=[...new Set(raw.bookmarks.filter(id=>byId.has(id)))];
 for(const [id,r] of Object.entries(raw.results))if(byId.has(id)&&r&&Number.isInteger(r.attempts)&&r.attempts>0&&Number.isInteger(r.correct)&&r.correct>=0&&r.correct<=r.attempts&&typeof r.lastCorrect==='boolean')s.results[id]={attempts:Math.min(r.attempts,1000000),correct:Math.min(r.correct,1000000),lastCorrect:r.lastCorrect,lastAnswer:[1,2,3,4].includes(r.lastAnswer)?r.lastAnswer:null,updatedAt:Number(r.updatedAt)||0};
 s.sessions=raw.sessions.map(cleanSession).filter(s=>s&&s.finishedAt).slice(0,100);s.active=cleanSession(raw.active);return s;
}
