function conceptButton(id,label='관련 개념'){const q=byId.get(id),n=relatedNotes(q).length;return `<button class="btn concept-btn" data-action="concept-modal" data-id="${id}" aria-label="${label} 보기">${icon('bulb')} ${label}${n?`<span class="mini-count">${n}</span>`:''}</button>`;}
