function questionLabel(q,exam=contextExam()){const id=examOccurrence(q,exam);return id?`${exam} · ${occurrenceNumber(id)}번${id!==q.id?` · 대표 원문 ${q.exam} ${q.number}번`:''}`:`${q.exam} · ${q.number}번`;}
