function empty(i,h,p,button='학습 시작하기'){return `<div class="empty"><div class="empty-icon">${icon(i)}</div><h2>${h}</h2><p>${p}</p><button class="btn primary" data-action="home">${button}${icon('arrow')}</button></div>`;}
// Search ignores spaces and PDF line breaks ('비재무적' finds '비재\n무적'); every query word must match.
const searchCache=new Map();
function searchText(q){if(!searchCache.has(q.id))searchCache.set(q.id,[q.text,q.exam,q.id,parts.get(q.part).name,q.subject,`${q.number}번`,...q.tags,...q.occurrences].join('|').toLowerCase().replace(/\s+/g,''));return searchCache.get(q.id);}
const EXAM=/^\d{4}-(?:0[1-9]|1[0-2])$/,QUESTION_ID=/^\d{4}-(?:0[1-9]|1[0-2])-\d{3}$/,QUESTION_NUMBER=/^\d+번$/;
function parseSearch(query){const terms=query.toLowerCase().split(/\s+/).filter(Boolean);return {exams:terms.filter(t=>EXAM.test(t)),ids:terms.filter(t=>QUESTION_ID.test(t)),numbers:terms.filter(t=>QUESTION_NUMBER.test(t)).map(t=>Number(t.slice(0,-1))),text:terms.filter(t=>!EXAM.test(t)&&!QUESTION_ID.test(t)&&!QUESTION_NUMBER.test(t))};}
