 if(!f.text.every(t=>searchText(q).includes(t))||!f.ids.every(id=>q.occurrences.includes(id)))return false;
 if(!f.exams.every(exam=>q.occurrences.some(id=>id.startsWith(exam+'-')&&f.numbers.every(n=>occurrenceNumber(id)===n))))return false;
 if(f.ids.length&&!f.ids.every(id=>f.numbers.every(n=>occurrenceNumber(id)===n)))return false;
