// One-line stem for list cards (the PDF bullet glyph Ÿ is shown as •): PDF wraps follow stemBreaks (j joins without a space), other breaks become spaces.
function markTerms(t,query){const ts=String(query||'').trim().split(/\s+/).filter(Boolean);if(!ts.length)return esc(t);const re=new RegExp(ts.map(x=>[...x].map(c=>c.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('\\s*')).join('|'),'gi');let out='',i=0;for(const m of t.matchAll(re)){if(!m[0])continue;out+=esc(t.slice(i,m.index))+'<mark>'+esc(m[0])+'</mark>';i=m.index+m[0].length;}return (out+esc(t.slice(i))).replaceAll('</mark><mark>','');}
function previewStem(q){const b=(D.stemBreaks||{})[q.id]||'';return q.stem.replace(/Ÿ(?=\s)/g,'•').split('\n').reduce((s,l,i)=>i===0?l:s.replace(/\s+$/,'')+(b[i-1]==='j'?'':' ')+l.replace(/^\s+/,''),'').replace(/[\uE000-\uF8FF]/g,'').replace(/\s+/g,' ').trim().replace(UNIT_GAP,(m,d,u,n)=>UNIT_SKIP.has(u+n)?m:d+u).slice(0,180);}
