function instructionsHtml(t){const items=String(t||'').split(/ü\s*/).map(x=>tidyUnits(x.replace(/\s+/g,' ').trim())).filter(Boolean);return items.length>1||/^\s*ü/.test(t)?`<ul class="instruction-list">${items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:`<p>${esc(t)}</p>`;}
// PDF text separates numbers from units ('1 월 1 일', '2,000,000 원', '20 %'); attach them for display,
