const UNIT_GAP=/(\d) (개월|원|년|월|일|개|%|단위|시간|명|주|회|배|억|만|천|kg)(?=([가-힣]?))/g,UNIT_SKIP=new Set(['회계','회사','주식','주주','주요','주된','일반']);
