function partSelect(){const groups=new Map();for(const p of ORDERED.filter(p=>!list.subject||p.subject===list.subject)){const g=(list.subject?'':p.subject+' · ')+p.chapter;if(!groups.has(g))groups.set(g,[]);groups.get(g).push(p);}return `<select class="select" id="library-part" aria-label="파트 필터"><option value="">전체 파트</option>${[...groups].map(([g,ps])=>`<optgroup label="${esc(g)}">${ps.map(p=>`<option value="${p.id}" ${list.part===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</optgroup>`).join('')}</select>`;}
