function library(){const copy={library:['QUESTION LIBRARY','문제 둘러보기','회차(예: 2024-11)와 과목으로 좁혀 번호 순서대로 풀어 보세요. 2024-11 1번을 검색하면 각 과목의 1번만 찾습니다.'],wrong:['LEARN FROM MISTAKES','오답 노트','최근에 틀린 문제를 모았어요. 다시 맞히면 오답 노트에서 빠집니다.'],bookmarks:['YOUR COLLECTION','즐겨찾기','다시 보고 싶은 문제를 나만의 목록으로 모아 보세요.']}[route];return title(...copy)+`<div class="view-toolbar"><input type="search" id="library-query" value="${esc(list.query)}" placeholder="문제 내용, 파트, 태그, 회차(예: 2024-11) 검색" aria-label="문제 검색"><select class="select" id="library-subject" aria-label="과목 필터"><option value="">전체 과목</option>${(()=>{const base=route==='wrong'?wrongIds():route==='bookmarks'?state.bookmarks:null,cnt={};if(base)for(const id of base){const q=byId.get(id);if(q)cnt[q.subject]=(cnt[q.subject]||0)+1;}return subjects.map(s=>`<option value="${s}" ${list.subject===s?'selected':''}>${s}${base?` (${cnt[s]||0})`:''}</option>`).join('');})()}</select>${partSelect()}<label class="check-row explanation-filter"><input id="library-explanations" type="checkbox" ${list.explanationsOnly?'checked':''}> 해설 있는 문제만</label></div><div id="library-results">${libraryRows()}</div>`;}
function shuffled(rows){const a=[...rows];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
